def populate_job_and_application_snapshots(apps, schema_editor):
    Job = apps.get_model("core", "Job")
    Application = apps.get_model("core", "Application")
    for job in Job.objects.all().iterator():
        job.status = "open" if job.is_active else "closed"
        job.deadline = job.expires_at
        job.save(update_fields=("status", "deadline"))
    for application in Application.objects.select_related("job").iterator():
        if application.job_id:
            application.job_title_snapshot = application.job.title
            application.job_company_snapshot = application.job.company
            application.application_url_snapshot = application.job.application_url
            application.save(update_fields=(
                "job_title_snapshot", "job_company_snapshot", "application_url_snapshot",
            ))


